#!/usr/bin/env python3
"""news-image-20261118 V2 — "Sum up 18 November's world news in one image".

Writes the finished 1024x1024 front-page PNG (55 stories, 13 featured)
to $MAKEFUN_OUTPUT_DIR/entry.png (fallback /output/entry.png if /output
exists, else output/entry.png). Stdlib only. Deterministic: two runs
write byte-identical files. No network, no randomness.
"""
import base64
import os
import zlib

DATA = [
    "",
    "",
    "",
    "",
    "",
]


def main():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if not out_dir:
        if os.path.isdir("/output"):
            out_dir = "/output"
        else:
            out_dir = "output"
    os.makedirs(out_dir, exist_ok=True)
    png = zlib.decompress(base64.b64decode("".join(DATA)))
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(png)


if __name__ == "__main__":
    main()
